setup.run:
printf 'server {
    listen 80;
    server_name ana.example;
    root /var/www/ana.example;
    index index.html;
}
' > /etc/nginx/sites-available/ana.example && ln -s /etc/nginx/sites-available/ana.example /etc/nginx/sites-enabled/ && rm /etc/nginx/sites-enabled/default && systemctl reload nginx

apt-get install -y -q nftables >/dev/null 2>&1 && printf '#!/usr/sbin/nft -f
flush ruleset

table inet filter {
    chain input {
        type filter hook input priority filter; policy drop;
        iif lo accept
        ct state established,related accept
        tcp dport { 22, 80, 443 } accept
        icmp type echo-request accept
    }
}
' > /etc/nftables.conf && systemctl enable --now nftables >/dev/null 2>&1
